ALTER TABLE "t_tutors" ADD COLUMN "annotations" json DEFAULT '{"mode":"required","ai":[{"key":"isCorrect","question":"Ist die Aussage des Tutors vollständig korrekt (fiktive Szenarien / Resultate ausgenommen)? ","tooltip":"Enthält die Aussage falsche, ungenaue, verzerrte oder unvollständige Anteile – oder ist sie klar, vollständig und korrekt formuliert? Fiktive Szenarien und Resultate, die der Tutor für das Fallbeispiel generiert, können ignoriert werden.","scale":"yes-no"}],"user":[{"key":"externalResource","question":"Haben Sie für Ihre Antwort externe Ressourcen gebraucht?","tooltip":"Haben Sie bei der Beurteilung der Qualität der Aussage des Tutors ODER bei der Ausarbeitung Ihrer Antwort, externe Quellen wie z.B. Unterrichtsmaterial, Google, Websites usw. genutzt?","scale":"yes-no"},{"key":"thoughtAboutIndex","question":"Wie aktiv haben Sie nachgedacht (0 = gar nicht, 10 = sehr aktiv)?","tooltip":"Aktives Nachdenken bedeutet, dass Sie sich bewusst mit dem Inhalt auseinandergesetzt haben – etwa indem Sie sich selbst Fragen gestellt, kritisch reflektiert, das Thema mit bereits Gelerntem verknüpft oder an konkrete Beispiele und Praxissituationen gedacht haben. Aktives Nachdenken zahlt sich aus – es verbessert nicht nur Ihr Verständnis, sondern auch Ihren Lernerfolg.","scale":"0-10"}]}'::json NOT NULL;